readonly struct AttemptKey(string tenant, string attemptId) : IEquatable<AttemptKey>
{
    public string Tenant { get; } = tenant;
    public string AttemptId { get; } = attemptId;

    public bool Equals(AttemptKey other) =>
        Tenant == other.Tenant && AttemptId == other.AttemptId;

    public override bool Equals(object? obj) =>
        obj is AttemptKey other && Equals(other);

    public override int GetHashCode() => HashCode.Combine(Tenant, AttemptId);
}

var inflight = new Dictionary<AttemptKey, int>();
inflight[new AttemptKey("acme", "a-1")] = 1;
var n = inflight[new AttemptKey("acme", "a-1")]; // 1 — value equality, not identity
